def tasks() -> list[dict]:
    rows = []
    for index, (category, owner, action, priority, secondary, text) in enumerate(RAW, start=1):
        rows.append(
            {
                "id": f"pw-{index:03d}",
                "category": category,
                "task": text,
                "gold_owner": owner,
                "gold_action": action,
                "gold_priority": priority,
                "gold_secondary": secondary,
            }
        )
    return rows


def main() -> None:
    rows = tasks()
    path = Path(__file__).with_name("tasks.jsonl")
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=True) + "\n")
    print(f"wrote {len(rows)} {path}")


if __name__ == "__main__":
    main()
